esbmc_test_source:
contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function test(address receiver, uint amount) public { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(receiver != address(0));
        require(address(this).balance >= amount);

        uint beforeBal = receiver.balance;

        c.sendTo(receiver, amount); if (__ESBMC_reverted()) return;

        uint afterBal = receiver.balance;

        assert(afterBal == beforeBal + amount);
    }

    receive() external payable {}
    fallback() external payable {}
}

