pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {MyContract as MyContract} from "../src/MyContract.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    MyContract c;

    function setUp() public {
        c = new MyContract();
    }

    function _test(address receiver, uint256 amount) internal {
        vm.deal(address(c), VALUE_CAP);
        vm.assume(receiver != address(0));
        vm.assume(address(this).balance >= amount);
        uint beforeBal = receiver.balance;
        try c.sendTo(receiver, amount) {} catch { return; }
        uint afterBal = receiver.balance;
        assertTrue(afterBal == beforeBal + amount);
    }

    function testFuzz_test(address receiver, uint256 amount) public {
        _test(receiver, amount);
    }

    receive() external payable {}

    fallback() external payable {}
}

